export function parseInteger(s: unknown): number {
  const value = Number(s);
  if (!Number.isFinite(value) || !Number.isInteger(value)) {
    throw new Error(`Not an integer: ${String(s)}`);
  }
  return value;
}

export function parseInteger(s: string): number | null {
  const value = Number(s);
  if (!Number.isFinite(value) || !Number.isInteger(value)) {
    return null;
  }
  return value;
}

export function parseInt(s: string): number {
  const value = Number(s);
  if (!Number.isFinite(value) || !Number.isInteger(value)) {
    throw new Error(`Not an integer: ${s}`);
  }
  return value;
}
